def calculate_amount_for_rent(rent):
    if rent.start_date and rent.end_date:
        days = (rent.end_date - rent.start_date).days or 1
        try:
            vehicle = rent.vehicle
            price = vehicle.price
        except Exception:
            price = 0
        return Decimal(days) * Decimal(price)
    return Decimal(0)


def populate_amounts(apps, schema_editor):
    RequestRent = apps.get_model('chat', 'RequestRent')
    Trip = apps.get_model('chat', 'Trip')

    for rent in RequestRent.objects.select_related('organizer__renter'):
        try:
            amount = calculate_amount_for_rent(rent)

            if rent.promocode:
                amount -= amount * Decimal(rent.promocode.total) / Decimal(100)
            if rent.bonus:
                amount -= rent.bonus

            rent.amount = max(amount, Decimal(0))
            rent.save(update_fields=["amount"])
        except Exception as e:
            print(f"Ошибка при обработке RequestRent ID={rent.id}: {e}")

    for trip in Trip.objects.select_related('organizer'):
        try:
            rent = RequestRent.objects.filter(
                object_id=trip.object_id,
                start_date=trip.start_date,
                end_date=trip.end_date
            ).first()

            if rent and rent.amount:
                trip.amount = rent.amount
                trip.save(update_fields=["amount"])
        except Exception as e:
            print(f"Ошибка при обработке Trip ID={trip.id}: {e}")


